30	constexpr int kLastLayerSize = 3;
31	constexpr double kLower = -1.0;
32	constexpr double kUpper = 1.0;
33	constexpr double kMax = 2.8;
34	constexpr double kStride0 = 0.5;
35	constexpr double kStride1 = 0.6;
36	constexpr double kStep = 1.0e-6;
37	
38	std::vector<double> make_table() {
39	  const int segment_count = 10;
40	  std::vector<double> table(segment_count * kLastLayerSize * 6);
41	  for (int segment = 0; segment < segment_count; ++segment) {
42	    for (int layer = 0; layer < kLastLayerSize; ++layer) {
43	      const int base = segment * kLastLayerSize * 6 + layer * 6;
44	      const double sign = (segment % 2 == 0) ? 1.0 : -1.0;
45	      table[base + 0] = 0.42 + 0.31 * segment - 0.07 * layer;
46	      table[base + 1] = sign * (0.83 + 0.11 * layer) + 0.03 * segment;
47	      table[base + 2] = -0.09 + 0.025 * segment + 0.015 * layer;
48	      table[base + 3] = 0.035 * (layer + 1) - 0.012 * segment;
49	      table[base + 4] = -0.006 * (segment + 1) + 0.002 * layer;
50	      table[base + 5] = 0.0015 * (segment % 3 - 1) + 0.0007 * (layer + 1);
51	    }
52	  }
53	  return table;
54	}
55	
56	const std::vector<double> kTableInfo = {
57	    kLower, kUpper, kMax, kStride0, kStride1, -1.0};
58	const std::vector<double> kWeights = {0.72, -0.41, 0.23};
59	const std::vector<double> kEnv = {1.0, -0.24, 0.37, -0.18};
60	const std::vector<double> kAdjoint = {
61	    0.53, -0.17, 0.29,
62	    -0.31, 0.19, -0.11,
63	    0.23, -0.07, 0.13,
64	    -0.05, 0.09, -0.21};
