66	double dot(const std::vector<double>& left, const std::vector<double>& right) {
67	  double value = 0.0;
68	  for (std::size_t ii = 0; ii < left.size(); ++ii) {
69	    value += left[ii] * right[ii];
70	  }
71	  return value;
72	}
