107	      dy_dem_x.data(), dy_dem.data(), dy_dtwo.data(), table.data(),
108	      kTableInfo.data(), em_x.data(), kEnv.data(), nullptr, kAdjoint.data(), 1,
109	      1, kLastLayerSize, false);
