113	double central_difference(const std::function<double(double)>& fn,
114	                          const double x) {
115	  return (fn(x + kStep) - fn(x - kStep)) / (2.0 * kStep);
116	}
117	
118	double increment_gap(const std::function<double(double)>& fn,
119	                     const double x) {
120	  const double left = (fn(x) - fn(x - kStep)) / kStep;
121	  const double right = (fn(x + kStep) - fn(x)) / kStep;
122	  return std::abs(left - right);
123	}
