125	void probe_family(const std::string& family,
126	                  const std::function<double(double)>& value_fn,
127	                  const std::function<double(double)>& sensitivity_fn) {
128	  const std::vector<double> points = {
129	      kLower - 0.31, kLower - 0.17, kLower, kLower + 0.23, 0.15,
130	      kUpper + 0.34, kMax - 0.09, kMax, kMax + 0.17, kMax + 0.31};
131	
132	  double value_min = std::numeric_limits<double>::infinity();
133	  double value_max = -std::numeric_limits<double>::infinity();
134	  double max_sensitivity_gap = 0.0;
135	  double max_increment_gap = 0.0;
136	  for (const double x : points) {
137	    const double value = value_fn(x);
138	    const double sensitivity = sensitivity_fn(x);
139	    const double finite_difference = central_difference(value_fn, x);
140	    value_min = std::min(value_min, value);
141	    value_max = std::max(value_max, value);
142	    max_sensitivity_gap =
143	        std::max(max_sensitivity_gap, std::abs(sensitivity - finite_difference));
144	    max_increment_gap = std::max(max_increment_gap, increment_gap(value_fn, x));
145	  }
146	  std::cout << "SUMMARY " << family << " " << points.size() << " "
147	            << std::setprecision(17) << value_min << " " << value_max << " "
148	            << max_sensitivity_gap << " " << max_increment_gap << "\n";
149	}
