#include "tabulate.h"
#include <cmath>
#include <functional>
#include <iomanip>
#include <iostream>
#include <string>
#include <vector>

namespace {
constexpr int kLastLayerSize = 3;
constexpr double kLower = -1.0;
constexpr double kUpper = 1.0;
constexpr double kMax = 2.8;
constexpr double kStride0 = 0.5;
constexpr double kStride1 = 0.6;
constexpr double kStep = 1.0e-6;

std::vector<double> make_table() {
  const int segment_count = 10;
  std::vector<double> table(segment_count * kLastLayerSize * 6);
  for (int segment = 0; segment < segment_count; ++segment) {
    for (int layer = 0; layer < kLastLayerSize; ++layer) {
      const int base = segment * kLastLayerSize * 6 + layer * 6;
      const double sign = (segment % 2 == 0) ? 1.0 : -1.0;
      table[base + 0] = 0.42 + 0.31 * segment - 0.07 * layer;
      table[base + 1] = sign * (0.83 + 0.11 * layer) + 0.03 * segment;
      table[base + 2] = -0.09 + 0.025 * segment + 0.015 * layer;
      table[base + 3] = 0.035 * (layer + 1) - 0.012 * segment;
      table[base + 4] = -0.006 * (segment + 1) + 0.002 * layer;
      table[base + 5] = 0.0015 * (segment % 3 - 1) + 0.0007 * (layer + 1);
    }
  }
  return table;
}

const std::vector<double> kTableInfo = {kLower, kUpper, kMax, kStride0, kStride1, -1.0};
const std::vector<double> kWeights = {0.72, -0.41, 0.23};
const std::vector<double> kEnv = {1.0, -0.24, 0.37, -0.18};
const std::vector<double> kAdjoint = {
    0.53, -0.17, 0.29,
    -0.31, 0.19, -0.11,
    0.23, -0.07, 0.13,
    -0.05, 0.09, -0.21};

double dot(const std::vector<double>& left, const std::vector<double>& right) {
  double value = 0.0;
  for (std::size_t ii = 0; ii < left.size(); ++ii) value += left[ii] * right[ii];
  return value;
}

double radial_value(const std::vector<double>& table, const double x) {
  std::vector<double> out(kLastLayerSize);
  const std::vector<double> em = {x};
  deepmd::tabulate_fusion_se_r_cpu<double>(out.data(), table.data(), kTableInfo.data(), em.data(), 1, 1, kLastLayerSize);
  return dot(out, kWeights);
}
double radial_sensitivity(const std::vector<double>& table, const double x) {
  std::vector<double> dy_dem(1);
  const std::vector<double> em = {x};
  deepmd::tabulate_fusion_se_r_grad_cpu<double>(dy_dem.data(), table.data(), kTableInfo.data(), em.data(), kWeights.data(), 1, 1, kLastLayerSize);
  return dy_dem[0];
}
double angular_value(const std::vector<double>& table, const double x) {
  std::vector<double> out(4 * kLastLayerSize);
  const std::vector<double> em_x = {x};
  deepmd::tabulate_fusion_se_a_cpu<double>(out.data(), table.data(), kTableInfo.data(), em_x.data(), kEnv.data(), nullptr, 1, 1, kLastLayerSize, false);
  return dot(out, kAdjoint);
}
double angular_sensitivity(const std::vector<double>& table, const double x) {
  std::vector<double> dy_dem_x(1);
  std::vector<double> dy_dem(4);
  std::vector<double> dy_dtwo(1);
  const std::vector<double> em_x = {x};
  deepmd::tabulate_fusion_se_a_grad_cpu<double>(dy_dem_x.data(), dy_dem.data(), dy_dtwo.data(), table.data(), kTableInfo.data(), em_x.data(), kEnv.data(), nullptr, kAdjoint.data(), 1, 1, kLastLayerSize, false);
  return dy_dem_x[0];
}
}  // namespace

int main() {
  const std::vector<double> table = make_table();
  const std::vector<double> points = {-1.31, -1.17, -1.0, -0.77, 0.15, 1.34, 2.71, 2.8, 2.97, 3.11};
  std::cout << std::setprecision(6);
  std::cout << "radial:\n   x        value      sens       fd         sensgap    incgap" << "\n";
  for (double x : points) {
    double v = radial_value(table, x), s = radial_sensitivity(table, x);
    double fd = (radial_value(table, x+kStep) - radial_value(table, x-kStep)) / (2*kStep);
    double left = (radial_value(table, x) - radial_value(table, x-kStep)) / kStep;
    double right = (radial_value(table, x+kStep) - radial_value(table, x)) / kStep;
    std::cout << x << "  " << v << "  " << s << "  " << fd << "  " << std::abs(s-fd) << "  " << std::abs(left-right) << "\n";
  }
  std::cout << "angular:\n   x        value      sens       fd         sensgap    incgap" << "\n";
  for (double x : points) {
    double v = angular_value(table, x), s = angular_sensitivity(table, x);
    double fd = (angular_value(table, x+kStep) - angular_value(table, x-kStep)) / (2*kStep);
    double left = (angular_value(table, x) - angular_value(table, x-kStep)) / kStep;
    double right = (angular_value(table, x+kStep) - angular_value(table, x)) / kStep;
    std::cout << x << "  " << v << "  " << s << "  " << fd << "  " << std::abs(s-fd) << "  " << std::abs(left-right) << "\n";
  }
  return 0;
}
