/*
    This inline function was designed to get the table info and bias value for
   current input xx! lower:      indicate the lower boundary of the first table;
    upper:      indicate the upper boundary of the first table as well as the
    lower boundary of the second table; max:        indicate the upper boundary
    of the second table; stride0:    indicate the stride of the first table;
    stride1:    indicate the stride of the second table;
    xx:         indicate the inputs value;
    table_idx:  indicate the location of table info of input value xx;
*/
template <typename FPTYPE>
inline void locate_xx(const FPTYPE& lower,
                      const FPTYPE& upper,
                      const FPTYPE& max,
                      const FPTYPE& stride0,
                      const FPTYPE& stride1,
                      FPTYPE& xx,
                      int& table_idx) {
  if (xx < lower) {
    table_idx = 0;
    xx = (FPTYPE)0.;
  } else if (xx < upper) {
    table_idx = (int)((xx - lower) / stride0);
    xx -= (table_idx * stride0 + lower);
  } else if (xx < max) {
    int first_stride = int((upper - lower) / stride0);
    table_idx = first_stride + (int)((xx - upper) / stride1);
    xx -= ((table_idx - first_stride) * stride1 + upper);
  } else {
    table_idx =
        int((upper - lower) / stride0) + (int)((max - upper) / stride1) - 1;
    xx = (FPTYPE)0.;
  }
}

input.new_string:
/*
    This inline function was designed to get the table info and bias value for
   current input xx! lower:      indicate the lower boundary of the first table;
    upper:      indicate the upper boundary of the first table as well as the
    lower boundary of the second table; max:        indicate the upper boundary
    of the second table; stride0:    indicate the stride of the first table;
    stride1:    indicate the stride of the second table;
    xx:         indicate the inputs value;
    table_idx:  indicate the location of table info of input value xx;
    xx_at_boundary (output, zero-initialized by the caller before the call):
    a flag marking that the input lies outside the stored polynomial support.
    In that case xx is the position of the supporting boundary (0 for the low
    support limit, stride for the high support limit) and table_idx is the
    index of the supporting segment, so the value evaluated there stays the
    same for every input beyond the support while its derivative is zero.
    This keeps tabulated values and sensitivities consistent with each other:
    points outside the table are answered by a flat saturation at the stored
    support edge instead of a new unconstrained high-order interval
    unsupported by table samples, and the value-sensitivity relationship of
    the polynomial intervals is preserved at every support boundary.
*/
template <typename FPTYPE>
inline void locate_xx(const FPTYPE& lower,
                      const FPTYPE& upper,
                      const FPTYPE& max,
                      const FPTYPE& stride0,
                      const FPTYPE& stride1,
                      FPTYPE& xx,
                      int& table_idx,
                      FPTYPE& xx_at_boundary) {
  xx_at_boundary = (FPTYPE)0.;
  if (xx < lower) {
    // below the stored support: pin to the low support limit
    table_idx = 0;
    xx = (FPTYPE)0.;
    xx_at_boundary = (FPTYPE)1.;
  } else if (xx < upper) {
    table_idx = (int)((xx - lower) / stride0);
    xx -= (table_idx * stride0 + lower);
  } else if (xx < max) {
    int first_stride = int((upper - lower) / stride0);
    table_idx = first_stride + (int)((xx - upper) / stride1);
    xx -= ((table_idx - first_stride) * stride1 + upper);
  } else {
    // beyond the stored support: pin to the high support limit
    table_idx =
        int((upper - lower) / stride0) + (int)((max - upper) / stride1) - 1;
    xx = (table_idx < int((upper - lower) / stride0)) ? stride0 : stride1;
    xx_at_boundary = (FPTYPE)1.;
  }
}

