// [upper,maxv) stride1
inline void locate_clamped(const TableParams& p, double x, int& idx, double& local) {
  double xc = x;
  if (xc < p.minv) xc = p.minv;
  if (xc > p.maxv) xc = p.maxv;
  if (xc < p.lower) {
    idx = (int)((xc - p.minv) / p.s1);
    local = xc - (idx * p.s1 + p.minv);
  } else if (xc < p.upper) {
