#include "tabulate.h"
#include <cmath>
#include <cstdio>
#include <vector>

namespace ref {
inline double poly(const double* t, int idx, int ll, int comp, double x) {
  double a0 = t[idx*ll*6+comp*6+0], a1 = t[idx*ll*6+comp*6+1], a2 = t[idx*ll*6+comp*6+2];
  double a3 = t[idx*ll*6+comp*6+3], a4 = t[idx*ll*6+comp*6+4], a5 = t[idx*ll*6+comp*6+5];
  return a0 + (a1 + (a2 + (a3 + (a4 + a5*x)*x)*x)*x)*x;
}
inline double poly1(const double* t, int idx, int ll, int comp, double x) {
  double a1 = t[idx*ll*6+comp*6+1], a2 = t[idx*ll*6+comp*6+2], a3 = t[idx*ll*6+comp*6+3];
  double a4 = t[idx*ll*6+comp*6+4], a5 = t[idx*ll*6+comp*6+5];
  return a1 + (2*a2 + (3*a3 + (4*a4 + 5*a5*x)*x)*x)*x;
}
inline double poly2(const double* t, int idx, int ll, int comp, double x) {
  double a2 = t[idx*ll*6+comp*6+2], a3 = t[idx*ll*6+comp*6+3], a4 = t[idx*ll*6+comp*6+4];
  double a5 = t[idx*ll*6+comp*6+5];
  return 2*a2 + (6*a3 + (12*a4 + 20*a5*x)*x)*x;
}
}  // namespace ref

static double g_max = 0.0;
static int g_checks = 0;

void chk(const char* what, double got, double want, double tol) {
  g_checks++;
  double d = std::fabs(got - want);
  if (d > g_max) g_max = d;
  if (d > tol) std::printf("MISMATCH %s: got %.12g want %.12g (diff %.3g)\n", what, got, want, d);
}

// locate helpers mirroring the expected (repaired) semantics
// a-layout: support [lower, mx]; [lower,upper) stride s0, [upper,mx) stride s1
// t-layout: support [mn, mx]; [mn,lower) s1, [lower,upper) s0, [upper,mx) s1
struct Loc { int idx; double local; bool outside; };

Loc loc_a(double x, double lower, double upper, double mx, double s0, double s1) {
  Loc r{0, 0.0, false};
  if (x < lower) { r.idx = 0; r.local = 0; r.outside = true; return r; }
  if (x < upper) { r.idx = (int)((x-lower)/s0); r.local = x - (r.idx*s0+lower); return r; }
  if (x < mx) { int f = (int)((upper-lower)/s0); r.idx = f + (int)((x-upper)/s1); r.local = x - ((r.idx-f)*s1+upper); return r; }
  r.idx = (int)((upper-lower)/s0) + (int)((mx-upper)/s1) - 1;
  r.local = (r.idx < (int)((upper-lower)/s0)) ? s0 : s1;
  r.outside = true;
  return r;
}

Loc loc_t(double x, double mn, double lower, double upper, double mx, double s0, double s1) {
  Loc r{0, 0.0, false};
  if (x < mn) { r.idx = 0; r.local = 0; r.outside = true; return r; }
  if (x < lower) { r.idx = (int)((x-mn)/s1); r.local = x - (r.idx*s1+mn); return r; }
  if (x < upper) { int f = (int)((lower-mn)/s1); r.idx = f + (int)((x-lower)/s0); r.local = x - ((r.idx-f)*s0+lower); return r; }
  if (x < mx) { int f = (int)((lower-mn)/s1) + (int)((upper-lower)/s0); r.idx = f + (int)((x-upper)/s1); r.local = x - ((r.idx-f)*s1+upper); return r; }
  r.idx = (int)((lower-mn)/s1) + (int)((upper-lower)/s0) + (int)((mx-upper)/s1) - 1;
  r.local = (r.idx < (int)((lower-mn)/s1) + (int)((upper-lower)/s0)) ? s0 : s1;
  r.outside = true;
  return r;
}

