#include "tabulate.h"
#include <cmath>
#include <cstdio>
#include <vector>

static double g_max = 0.0; static int g_checks = 0;
void chk(const char* what, double got, double want, double tol) {
  g_checks++; double d = std::fabs(got - want); if (d > g_max) g_max = d;
  if (d > tol) std::printf("MISMATCH %s: got %.12g want %.12g\n", what, got, want);
}

struct Loc { int idx; double local; bool outside; };
Loc loc_a(double x, double lower, double upper, double mx, double s0, double s1) {
  Loc r{0,0,false};
  if (x < lower) { r.outside = true; return r; }
  if (x < upper) { r.idx = (int)((x-lower)/s0); r.local = x - (r.idx*s0+lower); return r; }
  if (x < mx) { int f=(int)((upper-lower)/s0); r.idx = f+(int)((x-upper)/s1); r.local = x - ((r.idx-f)*s1+upper); return r; }
  r.idx = (int)((upper-lower)/s0)+(int)((mx-upper)/s1)-1;
  r.local = (r.idx < (int)((upper-lower)/s0)) ? s0 : s1;
  r.outside = true; return r;
}
double py(const double* t, int idx, int ll, int c, double x) {
  double a0=t[idx*ll*6+c*6+0],a1=t[idx*ll*6+c*6+1],a2=t[idx*ll*6+c*6+2],a3=t[idx*ll*6+c*6+3],a4=t[idx*ll*6+c*6+4],a5=t[idx*ll*6+c*6+5];
  return a0+(a1+(a2+(a3+(a4+a5*x)*x)*x)*x)*x;
}
double p1(const double* t, int idx, int ll, int c, double x) {
  double a1=t[idx*ll*6+c*6+1],a2=t[idx*ll*6+c*6+2],a3=t[idx*ll*6+c*6+3],a4=t[idx*ll*6+c*6+4],a5=t[idx*ll*6+c*6+5];
  return a1+(2*a2+(3*a3+(4*a4+5*a5*x)*x)*x)*x;
}

