    for (int i = 0; i < nloc; i++) {
      for (int j = 0; j < nnei; j++) { em_x[i*nnei+j] = (j < nnei-2) ? 0.1 + 0.37*j : 2.9; }
      em_x[i*nnei+0] = (i == 0) ? -1.0 : (i == 1 ? 2.5 : 0.7);
      for (int j = 0; j < nnei; j++) {
