        em[i*nnei*4+j*4+1] = 0.4*m*((j%2)-1);
        em[i*nnei*4+j*4+2] = -0.2*m*((j%4)-2);
        em[i*nnei*4+j*4+3] = 0.15*m*(j%5-2);
